const query = $json.query ?? {};
const cuisines = ['german', 'italian', 'indian', 'japanese', 'gourmet', 'fusion'];
const rawId = typeof query.id === 'string' ? query.id.trim() : '';
const rawCuisine = typeof query.cuisine === 'string' ? query.cuisine.trim() : '';
const rawPage = typeof query.page === 'string' ? query.page.trim() : '1';
const page = Number(rawPage);
const errors = [];

if (rawId && (rawCuisine || rawPage !== '1')) errors.push('id darf nicht mit Filter/Pagination kombiniert werden.');
if (rawCuisine && !cuisines.includes(rawCuisine)) errors.push('Unbekannte Cuisine.');
if (!Number.isInteger(page) || page < 1) errors.push('page muss eine positive Ganzzahl sein.');
if (rawId && /[.#$\[\]\/]/.test(rawId)) errors.push('Ungültige Recipe-ID.');

return [{ json: { valid: errors.length === 0, id: rawId || null, cuisine: rawCuisine || null, page, errorMessage: errors.join(' ') } }];

const request = $('Normalize Library Request').item.json;
const raw = $('Read Recipes from Firebase').item.json;
const records = raw && typeof raw === 'object' && !Array.isArray(raw) ? raw : {};

const favoriteRaw = $json;
const favorites =
  favoriteRaw && typeof favoriteRaw === 'object' && !Array.isArray(favoriteRaw)
    ? favoriteRaw
    : {};

const allowedCuisines = [
  'german',
  'italian',
  'indian',
  'japanese',
  'gourmet',
  'fusion',
];

function fail(message) {
  throw new Error(message);
}

function favoriteCount(id) {
  const entry = favorites[id];
  const count =
    entry && typeof entry === 'object' && !Array.isArray(entry)
      ? entry.count
      : 0;

  return Number.isInteger(count) && count >= 0 ? count : 0;
}

function validRecord(id, record) {
  if (!record || typeof record !== 'object' || Array.isArray(record)) {
    fail('Ungültiger Firebase-Record.');
  }

  if (
    record.schemaVersion !== 2 ||
    typeof record.createdAt !== 'string' ||
    Number.isNaN(Date.parse(record.createdAt))
  ) {
    fail('Ungültige Firebase-Metadaten.');
  }

  const recipe = record.payload;

  if (
    !recipe ||
    typeof recipe !== 'object' ||
    Array.isArray(recipe) ||
    recipe.id !== id
  ) {
    fail('Ungültiger Firebase-Recipe-Payload.');
  }

  if (typeof recipe.title !== 'string' || !recipe.title.trim()) {
    fail('Recipe-Titel fehlt.');
  }

  if (!allowedCuisines.includes(recipe.cuisine)) {
    fail('Recipe-Cuisine ist ungültig.');
  }

  return {
    recipe: {
      ...recipe,
      favoriteCount: favoriteCount(id),
    },
    createdAt: record.createdAt,
  };
}

if (request.id) {
  const record = records[request.id];

  if (!record) {
    return [{ json: { recipe: null } }];
  }

  return [
    {
      json: {
        recipe: validRecord(request.id, record).recipe,
      },
    },
  ];
}

const allItems = Object.entries(records).map(([id, record]) =>
  validRecord(id, record),
);

const topLiked = [...allItems]
  .filter((item) => item.recipe.favoriteCount > 0)
  .sort((a, b) =>
    b.recipe.favoriteCount - a.recipe.favoriteCount ||
    b.createdAt.localeCompare(a.createdAt),
  )
  .slice(0, 6)
  .map((item) => item.recipe);

let items = allItems;

if (request.cuisine) {
  items = items.filter(
    (item) => item.recipe.cuisine === request.cuisine,
  );
}

items.sort(
  (a, b) =>
    b.createdAt.localeCompare(a.createdAt) ||
    String(a.recipe.id).localeCompare(String(b.recipe.id)),
);

const total = items.length;
const pageSize = 20;
const pages = Math.max(1, Math.ceil(total / pageSize));
const page = Math.min(request.page, pages);
const offset = (page - 1) * pageSize;

return [
  {
    json: {
      items: items
        .slice(offset, offset + pageSize)
        .map((item) => item.recipe),
      topLiked,
      total,
      page,
      pages,
    },
  },
];

const body = $json.body ?? {};
const rawId = typeof body.id === 'string' ? body.id.trim() : '';
const errors = [];

if (!rawId) {
  errors.push('Recipe-ID fehlt.');
}

if (rawId && /[.#$\[\]\/]/.test(rawId)) {
  errors.push('Ungültige Recipe-ID.');
}

return [
  {
    json: {
      valid: errors.length === 0,
      id: rawId || null,
      errorMessage: errors.join(' '),
    },
  },
];

